package api

import (
	"fmt"

	"github.com/google/uuid"
)

// FileID identifies an indexed file. It is a UUIDv7 generated by the
// storage on first indexing and is the only way other modules refer to
// files.
type FileID uuid.UUID

// NewFileID generates a new time-ordered FileID.
func NewFileID() FileID {
	return FileID(uuid.Must(uuid.NewV7()))
}

// ParseFileID parses the canonical string form of a FileID.
func ParseFileID(s string) (FileID, error) {
	id, err := parseUUID(s, "file")
	return FileID(id), err
}

func (id FileID) String() string                { return uuid.UUID(id).String() }
func (id FileID) MarshalText() ([]byte, error)  { return uuid.UUID(id).MarshalText() }
func (id *FileID) UnmarshalText(b []byte) error { return unmarshalUUID((*uuid.UUID)(id), b, "file") }

// LocationID identifies a location (a directory accessed through a
// driver). It is a UUIDv7.
type LocationID uuid.UUID

// NewLocationID generates a new time-ordered LocationID.
func NewLocationID() LocationID {
	return LocationID(uuid.Must(uuid.NewV7()))
}

// ParseLocationID parses the canonical string form of a LocationID.
func ParseLocationID(s string) (LocationID, error) {
	id, err := parseUUID(s, "location")
	return LocationID(id), err
}

func (id LocationID) String() string               { return uuid.UUID(id).String() }
func (id LocationID) MarshalText() ([]byte, error) { return uuid.UUID(id).MarshalText() }
func (id *LocationID) UnmarshalText(b []byte) error {
	return unmarshalUUID((*uuid.UUID)(id), b, "location")
}

func parseUUID(s, kind string) (uuid.UUID, error) {
	id, err := uuid.Parse(s)
	if err != nil {
		return uuid.UUID{}, fmt.Errorf("%w: invalid %s id %q", ErrInvalidArgument, kind, s)
	}
	return id, nil
}

func unmarshalUUID(dst *uuid.UUID, b []byte, kind string) error {
	id, err := parseUUID(string(b), kind)
	if err != nil {
		return err
	}
	*dst = id
	return nil
}
